  },
  {
    "file": "tests/providers/matter/test_provider.py",
    "line": 770,
    "summary": "`_patch_user_reads` re-implements the conftest helper `single_user_read_from_listing` added in the same PR. Both answer the single read from the patched listing, with slightly different semantics: a snapshot dict versus a live lookup.",
    "failure_scenario": "There are two stubs for one contract. If the real single read changes, for example to return a new shape for an empty user, one stub may be updated and not the other, and the unit tests drift apart from each other."
  },
  {
    "file": "tests/providers/matter/test_provider.py",
    "line": 924,
    "summary": "The docstring of `test_preserves_slot_zero_resolved_by_user_index` describes an explicit `None` check that stops slot 0 from falling through to the fallback. That check no longer exists: a present `userIndex` never reaches the `credentialIndex` walk now, so the decoy user can't be reached.",
    "failure_scenario": "The test now only checks that `_dispatch_lock_operation` uses `is None` rather than a falsy test. The docstring and decoy describe an invariant that is gone, which misleads anyone maintaining the test."
  },
  {
    "file": "tests/providers/matter/test_provider.py",
    "line": 3668,
    "summary": "A new test docstring uses the abbreviation 'SDK' ('outside the SDK call').",
    "failure_scenario": "Breaks the AGENTS.md Code Style rule (CLAUDE.md points to AGENTS.md): '**Spell out acronyms** in code comments instead of using abbreviations.'"
  }
]
```

