python3 - <<'EOF'
import json,os,glob
for p in [os.path.expanduser("~/.claude.json")]+glob.glob(os.path.expanduser("~/.claude/*.json")):
    try: d=json.load(open(p))
    except Exception: continue
    def walk(o):
        if isinstance(o,dict):
            for k,v in o.items():
                if k=="mcphub-core": print(p, json.dumps({kk:vv for kk,vv in v.items() if kk!="headers"}))
                walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(d)
EOF

