input.command:
mkdir -p /tmp/mp && cat > /tmp/mp/mcp.py <<'EOF'
import json, os, sys, urllib.request
cfg = json.load(open(os.path.expanduser("~/.claude.json")))
def find(o):
    if isinstance(o, dict):
        if "mcphub-core" in o and isinstance(o["mcphub-core"], dict): return o["mcphub-core"]
        for v in o.values():
            r = find(v)
            if r: return r
    elif isinstance(o, list):
        for v in o:
            r = find(v)
            if r: return r
srv = find(cfg)
URL = srv["url"]; HDRS = dict(srv.get("headers") or {})
SID = None
def post(payload):
    global SID
    h = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream", **HDRS}
    if SID: h["Mcp-Session-Id"] = SID
    req = urllib.request.Request(URL, data=json.dumps(payload).encode(), headers=h, method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        SID = r.headers.get("Mcp-Session-Id") or SID
        body = r.read().decode()
    if not body.strip(): return None
    if body.lstrip().startswith("{"): return json.loads(body)
    msgs = [json.loads(l[5:]) for l in body.splitlines() if l.startswith("data:")]
    return msgs[-1] if msgs else None
post({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"cc-manual","version":"1"}}})
post({"jsonrpc":"2.0","method":"notifications/initialized"})
def call(name, args):
    r = post({"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":name,"arguments":args}})
    return r
if sys.argv[1] == "list":
    r = post({"jsonrpc":"2.0","id":2,"method":"tools/list"})
    for t in r["result"]["tools"]:
        if "mempalace" in t["name"] and any(k in t["name"] for k in sys.argv[2:] or [""]):
            print(t["name"], json.dumps(t.get("inputSchema",{}).get("properties",{}))[:600], "REQ", t.get("inputSchema",{}).get("required"))
else:
    print(json.dumps(call(sys.argv[1], json.loads(sys.argv[2])))[:3000])
EOF
python3 -I /tmp/mp/mcp.py list diary_write list_rooms add_drawer kg_add aaak 2>&1 | head -30

